fn smallest_list_length(list: &Vec<Vec<i32>>) -> usize {
    // Since `list` is guaranteed to be non-empty, we can safely unwrap the result of `min()`.
    list
        .iter()
        .map(|inner| inner.len())
        .min()
        .unwrap()
}

